 prior_path=B/'out/native/ashlar_range32_stage_r313/audited-summary.json';prior=json.loads(prior_path.read_text());source_path=B/'out/native/ashlar_scoped_maintenance_r300/audited-summary.json';source=json.loads(source_path.read_text());assert prior['state']=='First2M identity interval committed with complete20-field preservation';assert hashlib.sha256(source_path.read_bytes()).hexdigest()==prior['source_sha256'];budget=json.loads((B/'out/range32-comparison-budget-r308.json').read_text());p=B/'out/native/ashlar_range32_grow_r314';assert not p.exists();p.mkdir();c=Client(p,observation_timeout=200,cancel_after=90);start=time.monotonic();t=prior['table'];fields=json.loads((B/'out/cdf-image-oracle-r288.json').read_text())['roles']['edge_current']['fields'];cols=','.join(fields);extra=budget['partition_expression'];hs=row_hash_sql(fields);a={'state':'Preflighting19remaining source intervals','table':t,'uuid':prior['uuid'],'parent':prior['parent'],'source_sha256':{'prior':hashlib.sha256(prior_path.read_bytes()).hexdigest(),'parent':hashlib.sha256(source_path.read_bytes()).hexdigest()},'bounds':{'read_bytes':200000000000,'write_remote_bytes':45000000000,'spill_to_disk_bytes':5000000000,'wall_s':1500,'statement_cancel_after_s':90},'commits':prior['commits'],'version':prior['version'],'stages':[],'groups':prior['groups'],'prior_attempt_costs':prior['audit']['aggregate_with_prior_canceled_full_create']}
