  assert a['groups']==source['checks']['after'] and sum(int(r[1]) for r in a['groups'])==39990000;coverage=c.sql('partition-coverage',f"SELECT lookup_partition,count(*),count_if(lookup_partition<>{extra} OR lookup_partition IS NULL) FROM {t} VERSION AS OF {a['version']} GROUP BY lookup_partition ORDER BY lookup_partition");assert [int(r[0]) for r in coverage]==list(range(32)) and sum(int(r[1]) for r in coverage)==39990000 and all(int(r[2])==0 for r in coverage);a['partition_coverage']=coverage;a['final_detail']=detail('final-detail');metrics();a['aggregate_attempt_costs']={k:a['costs'][k]+a['prior_attempt_costs'][k] for k in a['costs']};a.update(state='All20source intervals populate full39.99M range32 candidate with complete carrier preservation',wall_s=time.monotonic()-start,qualification='19new2Midentity intervals plus independently qualified first interval;400complete20field multisets match immutable parent, exact full count and32derived partitions, underSHA256collision resistance. All actual commits accounted bySID; no unexplained outsidewrites. Full-field each-stage proof plus immutable ledger is not a general concurrent producer fence. Full ZORDER, repeated ingest publication, singleton/cold/concurrency and billion admission remain pending. No ACK, cleanup, pointer publication or compute resize.');save();(p/'live-statement.json').unlink();print(a['state'],a['costs'])
